fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let bw: i32 = w / 8;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, w / 2);
        host::display::state_set(2, h / 2);
        host::display::state_set(3, 3);
        host::display::state_set(4, -4);
        host::display::state_set(5, 3);
        host::display::state_set(6, 0);
        let mut i: i32 = 0;
        while i < 24 {
            host::display::state_set(20 + i, 1);
            i = i + 1;
        }
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(7) == 0;
    host::display::state_set(7, down);
    let phase: i32 = host::display::state_get(6);
    if phase == 1 || phase == 2 {
        if phase == 1 {
            host::display::clear(0x180404);
            host::display::draw_string(130, 200, "GAME OVER", 0xff4040, 4);
        } else {
            host::display::clear(0x041804);
            host::display::draw_string(120, 200, "WALL CLEARED", 0x00ff88, 4);
        }
        host::display::draw_string(140, 280, "TAP TO PLAY AGAIN", 0x808080, 2);
        if tap { host::display::state_set(0, 0); }
    } else {
        let mut bx: i32 = host::display::state_get(1);
        let mut by: i32 = host::display::state_get(2);
        let mut vx: i32 = host::display::state_get(3);
        let mut vy: i32 = host::display::state_get(4);
        let mut px: i32 = host::display::pointer_x() - 40;
        if px < 0 { px = 0; }
        if px > w - 80 { px = w - 80; }
        bx = bx + vx;
        by = by + vy;
        if bx < 0 { bx = 0; vx = -vx; }
        if bx > w - 10 { bx = w - 10; vx = -vx; }
        if by < 0 { by = 0; vy = -vy; }
        if by > h - 30 && vy > 0 && bx + 10 > px && bx < px + 80 {
            by = h - 30;
            vy = -vy;
        }
        if by > h {
            let lives: i32 = host::display::state_get(5) - 1;
            host::display::state_set(5, lives);
            if lives <= 0 {
                host::display::state_set(6, 1);
            }
            bx = w / 2;
            by = h / 2;
            vx = 3;
            vy = -4;
        }
        if by >= 40 && by < 94 {
            let row: i32 = (by - 40) / 18;
            let colm: i32 = bx / bw;
            if row >= 0 && row < 3 && colm >= 0 && colm < 8 {
                let slot: i32 = 20 + row * 8 + colm;
                if host::display::state_get(slot) == 1 {
                    host::display::state_set(slot, 0);
                    vy = -vy;
                }
            }
        }
        host::display::state_set(1, bx);
        host::display::state_set(2, by);
        host::display::state_set(3, vx);
        host::display::state_set(4, vy);
        host::display::clear(0x000008);
        let cols = [0xff4444, 0xffaa00, 0x00cc66];
        let mut alive: i32 = 0;
        let mut i: i32 = 0;
        while i < 24 {
            if host::display::state_get(20 + i) == 1 {
                alive = alive + 1;
                host::display::fill_rect((i % 8) * bw + 1, 40 + (i / 8) * 18, bw - 2, 16, cols[i / 8]);
            }
            i = i + 1;
        }
        if alive == 0 { host::display::state_set(6, 2); }
        host::display::fill_rect(px, h - 20, 80, 10, 0xffffff);
        host::display::fill_rect(bx, by, 10, 10, 0x00ffcc);
        let mut lf: i32 = 0;
        while lf < host::display::state_get(5) {
            host::display::fill_rect(w - 20 - lf * 18, 8, 12, 12, 0xff4444);
            lf = lf + 1;
        }
        host::display::draw_number(8, 6, alive, 0x808080, 2);
    }
    host::display::present();
}
